import os
import csv
import json
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"

def main():
    with open(os.path.join(DATA, "config.json")) as f:
        cfg = json.load(f)
    carbon_price = cfg["carbon_price_per_kg"]
    deferral_pen = cfg["deferral_penalty_per_slot_priority"]
    lat_pen = cfg["latency_penalty_per_ms_priority"]
    green_min = cfg["flexible_green_energy_min_share"]
    gap = cfg.get("solver_mip_gap", 0.0005)

    slots = []
    with open(os.path.join(DATA, "time_slots.csv")) as f:
        for row in csv.DictReader(f):
            slots.append((row["slot_id"], int(row["hour_index"])))
    slot_hour = {s: h for s, h in slots}
    slot_list = [s for s, _ in slots]

    regions = {}
    with open(os.path.join(DATA, "regions.csv")) as f:
        for row in csv.DictReader(f):
            regions[row["region_id"]] = {
                "res": row["data_residency"],
                "opex": float(row["opex_multiplier"]),
            }

    cap = {}
    with open(os.path.join(DATA, "region_slot_capacity.csv")) as f:
        for row in csv.DictReader(f):
            cap[(row["region_id"], row["slot_id"])] = float(row["compute_capacity_kw"]) - float(row["maintenance_reserved_kw"])

    env = {}
    with open(os.path.join(DATA, "region_slot_environment.csv")) as f:
        for row in csv.DictReader(f):
            env[(row["region_id"], row["slot_id"])] = (
                float(row["carbon_kg_per_kwh"]),
                float(row["energy_price_per_kwh"]),
                float(row["green_score"]),
            )

    workloads = {}
    with open(os.path.join(DATA, "workloads.csv")) as f:
        for row in csv.DictReader(f):
            workloads[row["workload_id"]] = {
                "dur": int(row["duration_slots"]),
                "power": float(row["power_kw"]),
                "earliest": row["earliest_slot"],
                "deadline": row["deadline_slot"],
                "prio": float(row["priority_weight"]),
                "res": row["data_residency"],
                "latmax": float(row["max_latency_ms"]),
                "flex": int(row["flexible_for_green_shift"]),
            }

    elig = {}
    with open(os.path.join(DATA, "workload_region_eligibility.csv")) as f:
        for row in csv.DictReader(f):
            w, r = row["workload_id"], row["region_id"]
            lat = float(row["latency_ms"])
            tcost = float(row["data_transfer_cost"])
            if lat > workloads[w]["latmax"] + 1e-9:
                continue
            if regions[r]["res"] != workloads[w]["res"]:
                continue
            elig.setdefault(w, {})[r] = (lat, tcost)

    # Precompute per (w, r, s)
    options = {}  # (w, r, s) -> dict
    for w, winfo in workloads.items():
        h0 = slot_hour[winfo["earliest"]]
        h1 = slot_hour[winfo["deadline"]]
        dur = winfo["dur"]
        for r, (lat, tcost) in elig.get(w, {}).items():
            opex = regions[r]["opex"]
            for s in slot_list:
                hs = slot_hour[s]
                if hs < h0 or hs + dur - 1 > h1:
                    continue
                energy = 0.0
                carbon = 0.0
                green = 0.0
                for k in range(dur):
                    ci, pr, gs = env[(r, slot_list[hs + k])]
                    energy += pr
                    carbon += ci
                    green += gs
                c = (winfo["power"] * opex * energy
                     + carbon_price * winfo["power"] * carbon
                     + lat_pen * winfo["prio"] * lat
                     + tcost
                     + deferral_pen * winfo["prio"] * (hs - h0))
                options[(w, r, s)] = {
                    "c": c,
                    "green_energy": winfo["power"] * green,
                    "energy_units": winfo["power"] * dur,
                    "occupies": [slot_list[hs + k] for k in range(dur)],
                }

    # Feasibility check: every workload has at least one option
    for w in workloads:
        if not any(k[0] == w for k in options):
            raise RuntimeError(f"No feasible option for {w}")

    model = Model("carbon_aware_compute")
    model.setParam("gaprel", gap)
    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    x = {}
    for key, opt in options.items():
        x[key] = model.addVar(name=f"x_{key[0]}_{key[1]}_{key[2]}", vtype="B", lb=0.0, ub=1.0, obj=opt["c"])

    # Assignment constraints
    for w in workloads:
        vars_w = [x[k] for k in options if k[0] == w]
        model.addCons(quicksum(vars_w) == 1, name=f"assign_{w}")

    # Capacity constraints per region, slot
    for r in regions:
        for s in slot_list:
            terms = []
            for (w, rr, ss), opt in options.items():
                if rr != r:
                    continue
                if s in opt["occupies"]:
                    terms.append(workloads[w]["power"] * x[(w, rr, ss)])
            if terms:
                model.addCons(quicksum(terms) <= cap[(r, s)], name=f"cap_{r}_{s}")

    # Green-shift constraint (flexible workloads only)
    flex_terms_green = []
    flex_terms_units = []
    for (w, r, s), opt in options.items():
        if workloads[w]["flex"]:
            flex_terms_green.append(opt["green_energy"] * x[(w, r, s)])
            flex_terms_units.append(opt["energy_units"] * x[(w, r, s)])
    if flex_terms_units:
        model.addCons(quicksum(flex_terms_green) >= green_min * quicksum(flex_terms_units), name="green_shift")

    model.setMinimize()
    model.optimize()

    status = model.getStatus()
    print("Status:", status)
    nsols = model.getNSols()
    print("NSols:", nsols)
    obj = None
    if nsols > 0:
        obj = model.getObjVal()
        print("Objective:", obj)

    # Extract solution
    assignment = {}
    if nsols > 0:
        for (w, r, s), var in x.items():
            if model.getVal(var) > 0.5:
                assignment[w] = (r, s)
    else:
        raise RuntimeError("No solution found")

    # Validate
    tol = cfg.get("feasibility_tolerance", 1e-5)
    assert len(assignment) == len(workloads), "Missing workloads in assignment"
    for w, (r, s) in assignment.items():
        assert (w, r, s) in options, f"Invalid option for {w}"
    # Capacity check
    for r in regions:
        for s in slot_list:
            used = 0.0
            for (w, rr, ss), opt in options.items():
                if rr == r and s in opt["occupies"] and (w, r, ss) in assignment and assignment[w] == (r, ss):
                    used += workloads[w]["power"]
            assert used <= cap[(r, s)] + tol, f"Capacity violated at {r},{s}: {used} > {cap[(r,s)]}"
    # Green check
    gsum = 0.0
    usum = 0.0
    for w, (r, s) in assignment.items():
        if workloads[w]["flex"]:
            opt = options[(w, r, s)]
            gsum += opt["green_energy"]
            usum += opt["energy_units"]
    share = gsum / usum if usum else 1.0
    assert share >= green_min - tol, f"Green share violated: {share} < {green_min}"
    print("Green share:", share)
    print("Validation passed")

    os.makedirs("/app/submissions", exist_ok=True)
    with open(OUT, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["workload_id", "region_id", "start_slot"])
        for w in sorted(workloads):
            r, s = assignment[w]
            writer.writerow([w, r, s])
    print("Wrote", OUT)
    model.free()

if __name__ == "__main__":
    main()
